    private String name;
    private double baseSalary;
    private int yearsOfService;

    public Employee(String name, double baseSalary, int yearsOfService) {
        this.name = name;
        this.baseSalary = baseSalary;
        this.yearsOfService = yearsOfService;
    }

    public String getName() {
        return name;
    }

    public double getBaseSalary() {
        return baseSalary;
    }

    public int getYearsOfService() {
        return yearsOfService;
    }
}

class SalaryCalculator {
    public double calculate(Employee employee) {
        return employee.getBaseSalary() + (employee.getYearsOfService() * 1000);
    }
}

class PaySlipPrinter {
    private SalaryCalculator calculator;

    public PaySlipPrinter(SalaryCalculator calculator) {
        this.calculator = calculator;
    }

    public void print(Employee employee) {
        System.out.println("Pay slip for " + employee.getName() + ": $" + calculator.calculate(employee));
    }
}

